sksl:
uniform shader image;
uniform float2 size;
uniform float phase;
uniform float amount;
uniform float scale;
layout(color) uniform half4 tint;
half4 effectMain(float2 coord){float2 p=coord*scale;float caust=pow(abs(sin(p.x*11.0+sin(p.y*7.0+phase))*cos(p.y*9.0-phase)),5.0);half4 c=image.eval(coord);return half4(clamp(c.rgb+ tint.rgb*half(caust*amount)*c.a,half3(0),half3(1)),c.a);}
uniform float effectOpacity;
half4 main(float2 coord) {
    half4 original = image.eval(coord);
    half4 processed = effectMain(coord);
    return mix(original, processed, half(clamp(effectOpacity, 0.0, 1.0)));
}
